// Package cursor is OpenLoco's mouse cursors (Ui.cpp initialiseCursors,
// Ui/Cursor.cpp): the CursorId enum, which ids are the system's own cursors
// (pointer, handPointer) and the 32x32 black-and-white bitmaps of the rest,
// each with its hot spot. table_gen.go is generated by tools/gen-cursors.
//
// SDL_CreateCursor makes a bitmap the system's cursor; Ebitengine can't set
// a cursor image, so goloco hides the system cursor while a bitmap one is
// chosen and draws Image at the mouse, less the hot spot (cmd/goloco
// cursor.go).
package cursor

import (
	"image"
	"image/color"
)

// Id is Ui::CursorId.
type Id uint8

type def struct {
	system     string // the SDL_SystemCursor of loadSystemCursor, "" for a bitmap
	hotX, hotY int
	rows       [32]string // 'X' black, '.' white, ' ' transparent (rawBlack, rawWhite, rawTransparent)
}

// System is the SDL system cursor the id stands for (SDL_SYSTEM_CURSOR_DEFAULT,
// SDL_SYSTEM_CURSOR_POINTER), "" for a bitmap cursor.
func (id Id) System() string {
	if id >= Count {
		return "SDL_SYSTEM_CURSOR_DEFAULT"
	}
	return table[id].system
}

// Hot is a bitmap cursor's hot spot: the bitmap's pixel at the mouse.
func (id Id) Hot() (x, y int) {
	if id >= Count {
		return 0, 0
	}
	return table[id].hotX, table[id].hotY
}

// Image is a bitmap cursor's 32x32 image (Cursor's constructor: 'X' data and
// mask set, black; '.' mask only, white; ' ' neither, transparent); nil for
// a system cursor.
func (id Id) Image() *image.RGBA {
	if id >= Count || table[id].system != "" {
		return nil
	}
	img := image.NewRGBA(image.Rect(0, 0, 32, 32))
	for y, row := range table[id].rows {
		for x, c := range row {
			switch c {
			case 'X':
				img.SetRGBA(x, y, color.RGBA{0, 0, 0, 255})
			case '.':
				img.SetRGBA(x, y, color.RGBA{255, 255, 255, 255})
			}
		}
	}
	return img
}
